const output = [];
const input = $input.first();

for (const item of input.json.data.latest_news) {
  output.push(item)
}

return output.slice(0, 2);

const seen = new Set();
const output = [];

for (const item of $input.all()) {
  const title = item.json.news_object.title;

  if (!seen.has(title)) {
    seen.add(title);
    output.push(item);
  }
}

return output;

const item = $input.first().json;

return {
  json: {
    prompt: `You are a financial news sentiment analyst.

Analyze this news:

Title: ${item.news_object.title}
Content: ${item.news_object.text}

Return STRICT JSON:

{
"title": "${item.news_object.title}",
"stock": "${item.stock_name}",
"sentiment": "bullish | bearish | neutral",
"confidence": 0-100,
"reason": "short explanation"
}`
  }
};

const out = [];

for (const item of $input.all()) {
  let text = item.json.content.parts[0].text;

  text = text.replace(/```json/g, "").replace(/```/g, "").trim();

  try {
    const parsed = JSON.parse(text);
    out.push({ json: parsed });
  } catch (err) {
    out.push({ json: { error: true, raw: text } });
  }
}

return out;

const output = [];

for (const item of $input.all()) {
  const data = item.json;

  let impact = 0;

  if (data.sentiment === "bullish") impact = data.confidence * 1.2;
  if (data.sentiment === "bearish") impact = data.confidence * -1.2;
  if (data.sentiment === "neutral") impact = data.confidence * 0.3;

  output.push({
    json: {
      ...data,
      impact_score: Math.round(impact)
    }
  });
}

return output;
